import { useState, useEffect } from "react";
import { useFormik } from "formik";
import Toast from "../components/Toast";
import { useAuth } from "../context/AuthContext";

const API_URL = process.env.REACT_APP_API_URL || "http://localhost:5000/api";

function validateProduct(values) {
  const errors = {};
  if (!values.name.trim()) errors.name = "Product name is required";
  if (!values.price) {
    errors.price = "Price is required";
  } else if (isNaN(values.price) || Number(values.price) < 0) {
    errors.price = "Price must be a positive number";
  }
  if (values.stock !== "" && (isNaN(values.stock) || Number(values.stock) < 0)) {
    errors.stock = "Stock must be a positive number";
  }
  return errors;
}

function AdminProducts() {
  const { token } = useAuth();
  const [products, setProducts]     = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading]       = useState(true);
  const [error, setError]           = useState(null);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingProduct, setEditing] = useState(null);
  const [deleteId, setDeleteId]     = useState(null);
  const [toast, setToast]           = useState(null);

  useEffect(() => { fetchProducts(); fetchCategories(); }, []);

  const fetchProducts = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(`${API_URL}/products`);
      if (!res.ok) throw new Error("Failed to load products");
      setProducts(await res.json());
    } catch (err) { setError(err.message); }
    finally { setLoading(false); }
  };

  const fetchCategories = async () => {
    try {
      const res = await fetch(`${API_URL}/categories`);
      if (res.ok) setCategories(await res.json());
    } catch {}
  };

  const openCreate = () => {
    setEditing(null);
    formik.resetForm();
    setDialogOpen(true);
  };

  const openEdit = (product) => {
    setEditing(product);
    formik.setValues({
      name:        product.name || "",
      description: product.description || "",
      price:       product.price || "",
      image:       product.image || "",
      category:    product.category?._id || product.category || "",
      stock:       product.stock ?? "",
      material:    product.material || "",
    });
    setDialogOpen(true);
  };

  const handleDelete = async () => {
    try {
      const res = await fetch(`${API_URL}/products/${deleteId}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) throw new Error("Failed to delete product");
      setToast({ message: "Product deleted", type: "success" });
      fetchProducts();
    } catch (err) {
      setToast({ message: err.message, type: "error" });
    } finally {
      setDeleteId(null);
    }
  };

  const formik = useFormik({
    initialValues: { name: "", description: "", price: "", image: "", category: "", stock: "", material: "" },
    validate: validateProduct,
    onSubmit: async (values, { setStatus, setSubmitting }) => {
      setStatus(null);
      try {
        const url    = editingProduct ? `${API_URL}/products/${editingProduct._id}` : `${API_URL}/products`;
        const method = editingProduct ? "PUT" : "POST";
        const res = await fetch(url, {
          method,
          headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
          body: JSON.stringify({ ...values, price: Number(values.price), stock: Number(values.stock) || 0 }),
        });
        if (!res.ok) {
          const data = await res.json();
          setStatus(data.message || "Operation failed");
          return;
        }
        setToast({ message: editingProduct ? "Product updated!" : "Product created!", type: "success" });
        setDialogOpen(false);
        fetchProducts();
      } catch (err) {
        setStatus("Network error. Please try again.");
      } finally {
        setSubmitting(false);
      }
    },
  });

  if (error) return <div className="alert alert-danger" style={{ borderRadius: 0 }}>{error}</div>;

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-3">
        <div>
          <h4 className="serif mb-0">Products</h4>
          <small className="text-muted">{products.length} total</small>
        </div>
        <button className="btn-af btn-af-sm" onClick={openCreate}>
          <i className="bi bi-plus me-1"></i> Add Product
        </button>
      </div>

      {loading ? (
        <div className="row g-3">
          {[1,2,3].map(n => <div key={n} className="col-12 col-sm-6 col-md-4"><div className="skeleton" style={{ height: 200 }}></div></div>)}
        </div>
      ) : (
        <div className="row g-3">
          {products.map((p) => (
            <div className="col-12 col-sm-6 col-md-4" key={p._id}>
              <div className="af-card" style={{ cursor: "default" }}>
                <div style={{ height: 140, background: "#f0ece6", display: "flex", alignItems: "center", justifyContent: "center", overflow: "hidden" }}>
                  {p.image
                    ? <img src={p.image} alt={p.name} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                    : <div style={{ width: "50%", height: "50%", border: "2px solid var(--border)" }}></div>
                  }
                </div>
                <div className="p-3">
                  <p className="mb-0" style={{ fontWeight: 600 }}>{p.name}</p>
                  <p className="text-muted mb-2" style={{ fontSize: "0.85rem" }}>${p.price}</p>
                  <div className="d-flex justify-content-between align-items-center">
                    <span className={`chip ${p.stock > 0 ? "" : "chip-dark"}`}>Stock: {p.stock}</span>
                    <div className="d-flex gap-1">
                      <button
                        onClick={() => openEdit(p)}
                        style={{ background: "none", border: "none", cursor: "pointer", color: "var(--gray)", fontSize: "1rem" }}
                      ><i className="bi bi-pencil"></i></button>
                      <button
                        onClick={() => setDeleteId(p._id)}
                        style={{ background: "none", border: "none", cursor: "pointer", color: "#c0392b", fontSize: "1rem" }}
                      ><i className="bi bi-trash"></i></button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          ))}
          {products.length === 0 && (
            <div className="col-12 text-center py-5 text-muted">No products yet.</div>
          )}
        </div>
      )}

      {/* Create/Edit Modal */}
      {dialogOpen && (
        <div className="modal d-flex" style={{ background: "rgba(0,0,0,0.5)", position: "fixed", inset: 0, zIndex: 300, alignItems: "center", justifyContent: "center" }}>
          <div style={{ background: "var(--white)", width: "100%", maxWidth: 520, maxHeight: "90vh", overflowY: "auto", border: "1px solid var(--border)" }}>
            <div className="d-flex justify-content-between align-items-center p-4" style={{ borderBottom: "1px solid var(--border)" }}>
              <h5 className="serif mb-0">{editingProduct ? "Edit Product" : "Add New Product"}</h5>
              <button onClick={() => setDialogOpen(false)} style={{ background: "none", border: "none", fontSize: "1.3rem", cursor: "pointer" }}>×</button>
            </div>

            <form onSubmit={formik.handleSubmit} noValidate className="p-4">
              {formik.status && (
                <div className="alert alert-danger py-2 mb-3" style={{ borderRadius: 0, fontSize: "0.83rem" }}>{formik.status}</div>
              )}

              <div className="mb-3">
                <label className="af-label">Product Name *</label>
                <input name="name" className={`af-input ${formik.touched.name && formik.errors.name ? "is-invalid" : ""}`}
                  value={formik.values.name} onChange={formik.handleChange} onBlur={formik.handleBlur} />
                {formik.touched.name && formik.errors.name && <p className="af-error">{formik.errors.name}</p>}
              </div>

              <div className="mb-3">
                <label className="af-label">Description</label>
                <textarea name="description" className="af-input" rows={3}
                  value={formik.values.description} onChange={formik.handleChange} />
              </div>

              <div className="row g-3 mb-3">
                <div className="col-6">
                  <label className="af-label">Price *</label>
                  <input type="number" name="price" className={`af-input ${formik.touched.price && formik.errors.price ? "is-invalid" : ""}`}
                    value={formik.values.price} onChange={formik.handleChange} onBlur={formik.handleBlur} />
                  {formik.touched.price && formik.errors.price && <p className="af-error">{formik.errors.price}</p>}
                </div>
                <div className="col-6">
                  <label className="af-label">Stock</label>
                  <input type="number" name="stock" className={`af-input ${formik.touched.stock && formik.errors.stock ? "is-invalid" : ""}`}
                    value={formik.values.stock} onChange={formik.handleChange} onBlur={formik.handleBlur} />
                  {formik.touched.stock && formik.errors.stock && <p className="af-error">{formik.errors.stock}</p>}
                </div>
              </div>

              <div className="mb-3">
                <label className="af-label">Image URL</label>
                <input name="image" className="af-input" value={formik.values.image} onChange={formik.handleChange} />
              </div>

              <div className="mb-3">
                <label className="af-label">Material</label>
                <input name="material" className="af-input" value={formik.values.material} onChange={formik.handleChange} />
              </div>

              <div className="mb-4">
                <label className="af-label">Category</label>
                <select name="category" className="af-input" value={formik.values.category} onChange={formik.handleChange}>
                  <option value="">None</option>
                  {categories.map((c) => <option key={c._id} value={c._id}>{c.name}</option>)}
                </select>
              </div>

              <div className="d-flex gap-2 justify-content-end">
                <button type="button" className="btn-af-outline btn-af-sm" onClick={() => setDialogOpen(false)}>Cancel</button>
                <button type="submit" className="btn-af btn-af-sm" disabled={formik.isSubmitting}>
                  {formik.isSubmitting ? "Saving..." : editingProduct ? "Update" : "Create"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Delete Confirm Modal */}
      {deleteId && (
        <div className="modal d-flex" style={{ background: "rgba(0,0,0,0.5)", position: "fixed", inset: 0, zIndex: 300, alignItems: "center", justifyContent: "center" }}>
          <div style={{ background: "var(--white)", width: "100%", maxWidth: 400, border: "1px solid var(--border)", padding: "32px" }}>
            <h5 className="serif mb-2">Delete Product?</h5>
            <p className="text-muted mb-4" style={{ fontSize: "0.88rem" }}>This action cannot be undone.</p>
            <div className="d-flex gap-2 justify-content-end">
              <button className="btn-af-outline btn-af-sm" onClick={() => setDeleteId(null)}>Cancel</button>
              <button className="btn-af btn-af-sm btn-af-danger" onClick={handleDelete}>Delete</button>
            </div>
          </div>
        </div>
      )}

      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </div>
  );
}

export default AdminProducts;
